import json
import re

def verify(tools, answer):
    try:
        # Helper to safely extract nested values
        def safe_get(obj, key, default=None):
            if isinstance(obj, dict):
                return obj.get(key, default)
            return default

        # 1. Extract the actual answer payload
        # If answer is wrapped in submit_result format, unwrap it
        if isinstance(answer, dict):
            # Check for submit_result wrapper keys
            if 'submitted_data' in answer:
                actual_answer = answer['submitted_data']
            elif 'result' in answer and isinstance(answer['result'], list):
                actual_answer = answer['result']
            elif 'status' in answer and 'message' in answer:
                # Might be a wrapper, try to find data in known keys
                for key in ['data', 'payload', 'content', 'items']:
                    if key in answer and isinstance(answer[key], list):
                        actual_answer = answer[key]
                        break
                else:
                    # If not found, assume answer itself is the result
                    actual_answer = answer
            else:
                # Direct array or unknown structure
                actual_answer = answer if isinstance(answer, list) else []
        else:
            actual_answer = answer if isinstance(answer, list) else []

        # Ensure we have a list
        if not isinstance(actual_answer, list):
            return {
                'passed': False,
                'message': 'Answer is not a list',
                'details': f'Got type: {type(actual_answer)}'
            }

        if not actual_answer:
            return {
                'passed': False,
                'message': 'Empty answer list',
                'details': 'No patterns extracted'
            }

        # 2. Use tools to retrieve actual data for verification
        # We'll use tools that contain microservice/architecture patterns
        # Based on tool names, the most relevant ones are:
        # - get_data_4_microservice_patterns_content
        # - get_architecture_patterns_microservices_content
        # - get_common_design_patterns_content
        # - get_the_ultimate_guide_content

        all_patterns_from_tools = []

        # Tool 1: Microservice patterns
        try:
            microservice_result = tools['get_data_4_microservice_patterns_content'](
                pattern_type='',
                min_bullet_count=0,
                search_text='',
                include_summary=True
            )
            if isinstance(microservice_result, dict) and 'result' in microservice_result:
                microservice_data = microservice_result['result']
                if isinstance(microservice_data, list):
                    all_patterns_from_tools.extend(microservice_data)
        except Exception:
            pass  # Continue with other tools

        # Tool 2: Architecture patterns
        try:
            arch_result = tools['get_architecture_patterns_microservices_content'](
                pattern_type='',
                section_type='',
                min_bullet_points=0,
                search_keywords=[]
            )
            if isinstance(arch_result, dict) and 'result' in arch_result:
                arch_data = arch_result['result']
                if isinstance(arch_data, list):
                    all_patterns_from_tools.extend(arch_data)
        except Exception:
            pass

        # Tool 3: Common design patterns (Event-Driven)
        try:
            design_result = tools['get_common_design_patterns_content'](
                section_heading='',
                min_bullet_count=0,
                search_term='',
                include_bullets=True
            )
            if isinstance(design_result, dict) and 'result' in design_result:
                design_data = design_result['result']
                if isinstance(design_data, list):
                    all_patterns_from_tools.extend(design_data)
        except Exception:
            pass

        # Tool 4: Ultimate guide (Event-Driven Architecture)
        try:
            guide_result = tools['get_the_ultimate_guide_content'](
                section_heading_filter='',
                contains_text='',
                min_bullet_points=0,
                include_all_bullets=False
            )
            if isinstance(guide_result, dict) and 'result' in guide_result:
                guide_data = guide_result['result']
                if isinstance(guide_data, list):
                    all_patterns_from_tools.extend(guide_data)
        except Exception:
            pass

        # 3. Extract pattern names from tool data for comparison
        tool_pattern_names = set()
        tool_pattern_data = {}  # name -> {heading, text, etc.}

        for item in all_patterns_from_tools:
            if not isinstance(item, dict):
                continue

            # Try to extract pattern name from various fields
            heading = safe_get(item, 'heading', '')
            title = safe_get(item, 'title', '')
            text = safe_get(item, 'text', '')

            # Look for pattern names in the content
            content = f'{heading} {title} {text}'.lower()

            # Common pattern names to look for
            pattern_keywords = [
                'saga', 'orchestration', 'choreography', 'publisher/subscriber',
                'pub/sub', 'event sourcing', 'cqrs', 'api gateway', 'circuit breaker',
                'bulkhead', 'retry', 'timeout', 'compensating transaction',
                'two-phase commit', 'saga pattern', 'orchestrator', 'choreography pattern'
            ]

            for keyword in pattern_keywords:
                if keyword in content:
                    tool_pattern_names.add(keyword)
                    if keyword not in tool_pattern_data:
                        tool_pattern_data[keyword] = {
                            'heading': heading,
                            'text': text[:200] if text else '',
                            'source': 'tool_data'
                        }

        # 4. Verify each entry in the answer
        verification_results = []
        all_passed = True

        for i, entry in enumerate(actual_answer):
            if not isinstance(entry, dict):
                verification_results.append({
                    'index': i,
                    'passed': False,
                    'reason': 'Entry is not a dictionary'
                })
                all_passed = False
                continue

            # Check required fields exist
            pattern_name = safe_get(entry, 'pattern_name', '')
            primary_purpose = safe_get(entry, 'primary_purpose', '')
            core_problem = safe_get(entry, 'core_problem_solved', '')
            source_doc = safe_get(entry, 'source_document', '')

            if not pattern_name or not primary_purpose or not core_problem or not source_doc:
                verification_results.append({
                    'index': i,
                    'passed': False,
                    'reason': 'Missing required field(s)',
                    'details': {
                        'has_pattern_name': bool(pattern_name),
                        'has_primary_purpose': bool(primary_purpose),
                        'has_core_problem': bool(core_problem),
                        'has_source_doc': bool(source_doc)
                    }
                })
                all_passed = False
                continue

            # Check if pattern name is plausible (exists in tool data)
            pattern_lower = pattern_name.lower()
            pattern_found_in_tools = False

            # Direct match
            if pattern_lower in tool_pattern_names:
                pattern_found_in_tools = True
            else:
                # Partial match or similar
                for tool_pattern in tool_pattern_names:
                    if tool_pattern in pattern_lower or pattern_lower in tool_pattern:
                        pattern_found_in_tools = True
                        break

            # Verify content is not trivial
            if len(primary_purpose.strip()) < 10 or len(core_problem.strip()) < 10:
                verification_results.append({
                    'index': i,
                    'passed': False,
                    'reason': 'Description too short/vague',
                    'details': {
                        'pattern_name': pattern_name,
                        'purpose_length': len(primary_purpose.strip()),
                        'problem_length': len(core_problem.strip())
                    }
                })
                all_passed = False
                continue

            # Check for excluded content (RFID, physical tech)
            entry_text = f'{pattern_name} {primary_purpose} {core_problem} {source_doc}'.lower()
            excluded_terms = ['rfid', 'radio frequency', 'physical', 'hardware', 'tag', 'reader']

            has_excluded_content = False
            for term in excluded_terms:
                if term in entry_text:
                    has_excluded_content = True
                    break

            if has_excluded_content:
                # Check if it's ONLY about RFID (should be excluded)
                # If pattern_name is actually a coordination pattern, it might still be valid
                # even if mentioned with RFID
                coordination_indicators = ['coordination', 'orchestrat', 'choreography', 
                                         'saga', 'pattern', 'protocol', 'api']
                has_coordination_context = any(indicator in entry_text for indicator in coordination_indicators)

                if not has_coordination_context:
                    verification_results.append({
                        'index': i,
                        'passed': False,
                        'reason': 'Excluded content (RFID/physical tech without clear coordination link)',
                        'details': {
                            'pattern_name': pattern_name,
                            'excluded_terms_found': [term for term in excluded_terms if term in entry_text]
                        }
                    })
                    all_passed = False
                    continue

            # Record verification result for this entry
            verification_results.append({
                'index': i,
                'passed': True,
                'pattern_name': pattern_name,
                'pattern_found_in_tools': pattern_found_in_tools,
                'source_document': source_doc
            })

        # 5. Overall verification
        if not verification_results:
            return {
                'passed': False,
                'message': 'No entries to verify',
                'details': 'Empty verification results'
            }

        # Count passed entries
        passed_count = sum(1 for r in verification_results if r.get('passed', False))
        total_count = len(verification_results)

        if passed_count == 0:
            return {
                'passed': False,
                'message': 'No entries passed verification',
                'details': verification_results
            }

        # Check if we have at least some valid patterns
        # We expect at least some coordination patterns based on the task
        coordination_patterns_found = False
        for result in verification_results:
            if result.get('passed', False):
                pattern_name = result.get('pattern_name', '').lower()
                coordination_keywords = ['saga', 'orchestrat', 'choreography', 'pub/sub', 
                                        'event', 'gateway', 'circuit', 'retry', 'timeout']
                if any(keyword in pattern_name for keyword in coordination_keywords):
                    coordination_patterns_found = True
                    break

        if not coordination_patterns_found:
            return {
                'passed': False,
                'message': 'No coordination patterns found in valid entries',
                'details': verification_results
            }

        return {
            'passed': all_passed,
            'message': f'Verified {passed_count}/{total_count} entries',
            'details': {
                'total_entries': total_count,
                'passed_entries': passed_count,
                'tool_patterns_found': len(tool_pattern_names),
                'verification_results': verification_results
            }
        }

    except Exception as e:
        # Catch any unexpected exception
        return {
            'passed': False,
            'message': f'Verification error: {str(e)}',
            'details': {'exception_type': type(e).__name__}
        }

